from PIL import Image
im = Image.open('/app/chess_board.png').convert('RGB')
px = im.load()
sq = 80
files = "abcdefgh"
out = open('/tmp/board.txt', 'w')
for r in range(8):
    for c in range(8):
        wcnt = bcnt = 0
        for y in range(r*sq, r*sq+sq):
