                if R > 200 and G > 200 and B > 200:
                    wcnt += 1
                elif R < 70 and G < 70 and B < 70:
                    bcnt += 1
        if wcnt + bcnt > 200:
            out.write(f"{files[c]}{8-r}: W={wcnt} B={bcnt}\n")
out.close()
print("ok")
